    bg = all_colors.most_common(1)[0][0]

    # Backup original grid
    orig = [row[:] for row in grid]

    # Find all connected components for each non-background color
    non_bg_colors = [c for c, n in all_colors.most_common() if c != bg]

    # For each cell, track if it gets a new color
    fill_rects = {}  # (color) -> list of (min_r, min_c, max_r, max_c)
    for color in non_bg_colors:
        rects = find_all_rectangles(grid, color)
        for bbox, _ in rects:
            fill_rects[color].append(bbox)

    # Fill each rectangle
    result = [row[:] for row in grid]
    for color, rects in fill_rects.items():
        for (min_r, min_c, max_r, max_c) in rects:
            for r in range(min_r, max_r + 1):
